  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly attributes a positive outcome, action, or policy to their own efforts, advocacy, or legislative work, thereby seeking recognition or taking personal responsibility for the result.",
    "clarification": "Credit-claiming is identified when the senator uses first-person language (e.g., 'I secured,' 'I authored,' 'I fought for') or explicitly links their actions to a tangible benefit or achievement. This includes highlighting their role in securing funding, introducing or passing legislation, or advocating for a cause that led to a specific positive outcome. The focus is on the senator's direct involvement and their explicit assertion of responsibility for the result.",
    "positive_examples": [
      {
        "document_id": "89",
